      "description": "A complete, beginner-friendly course in computer networking. Seven modules cover network types and devices, the OSI and TCP/IP models, Ethernet and Wi-Fi, IPv4 and IPv6 addressing with step-by-step subnetting, routing, TCP, UDP, DNS, DHCP and HTTP, network security, and how to design and troubleshoot a real network. 27 illustrated lessons with diagrams, tables, worked examples, quizzes and a final test.",
      "level": "intermediate",
      "edu_levels": [
        "secondary",
        "advanced",
        "college",
        "university",
        "professional"
      ],
      "category_slug": "computer-studies",
      "category_name": "Computer Studies",
      "is_free": true,
      "price": 0,
      "age_range": "13+",
      "language": "English",
      "instructor_name": "Smart21Brain",
      "certificate_enabled": true,
      "thumbnail_url": "images/courses/computer-networks.svg",
